/* ============================================================
   РЕНДЕР
   ============================================================ */

const contentEl = document.getElementById("content");
const searchEl = document.getElementById("search");
const countEl = document.getElementById("search-count");

let noResultsEl = null;

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function buildRuleHtml(rule, blockIndex, ruleIndex) {
  let html = `<div class="rule" data-block="${blockIndex}" data-rule="${ruleIndex}">`;
  html += `<div class="rule-text">${escapeHtml(rule.text)}</div>`;
  if (rule.note) {
    html += `<div class="rule-note"><strong>Примечание:</strong> ${escapeHtml(rule.note)}</div>`;
  }
  if (rule.penalty) {
    html += `<div class="rule-penalty"><strong>Наказание:</strong> ${escapeHtml(rule.penalty)}</div>`;
  }
  html += `</div>`;
  return html;
}

function render() {
  contentEl.innerHTML = "";

  DATA.forEach((block, blockIndex) => {
    const section = document.createElement("section");
    section.className = "block";
    section.dataset.block = blockIndex;

    const header = document.createElement("button");
    header.className = "block-header";
    header.type = "button";
    header.setAttribute("aria-expanded", "false");
    header.innerHTML = `
      <span class="block-title">${escapeHtml(block.title)}</span>
      <span class="block-arrow" aria-hidden="true"></span>
    `;
    header.addEventListener("click", () => {
      section.classList.toggle("open");
      header.setAttribute("aria-expanded", section.classList.contains("open"));
    });

    const body = document.createElement("div");
    body.className = "block-body";
    body.innerHTML = block.rules
      .map((rule, ruleIndex) => buildRuleHtml(rule, blockIndex, ruleIndex))
      .join("");

    section.appendChild(header);
    section.appendChild(body);
    contentEl.appendChild(section);
  });

  noResultsEl = document.createElement("div");
  noResultsEl.className = "no-results";
  noResultsEl.textContent = "Ничего не найдено.";
  noResultsEl.hidden = true;
  contentEl.appendChild(noResultsEl);
}

/* ============================================================
   ПОИСК
   ============================================================ */

function normalize(str) {
  return str.toLowerCase().replace(/ё/g, "е");
}

function highlightText(el, query) {
  // Сбрасываем предыдущую подсветку
  el.querySelectorAll("mark").forEach((m) => {
    const parent = m.parentNode;
    parent.replaceChild(document.createTextNode(m.textContent), m);
    parent.normalize();
  });

  if (!query) return;

  const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, null);
  const textNodes = [];
  while (walker.nextNode()) textNodes.push(walker.currentNode);

  const q = normalize(query);

  textNodes.forEach((node) => {
    const text = node.nodeValue;
    const lower = normalize(text);
    const idx = lower.indexOf(q);
    if (idx === -1) return;

    const before = text.slice(0, idx);
    const match = text.slice(idx, idx + query.length);
    const after = text.slice(idx + query.length);

    const frag = document.createDocumentFragment();
    if (before) frag.appendChild(document.createTextNode(before));
    const mark = document.createElement("mark");
    mark.textContent = match;
    frag.appendChild(mark);
    if (after) frag.appendChild(document.createTextNode(after));

    node.parentNode.replaceChild(frag, node);
  });
}

function performSearch(rawQuery) {
  const query = rawQuery.trim();
  const q = normalize(query);

  const blocks = contentEl.querySelectorAll(".block");
  let totalMatches = 0;
  let blocksWithMatches = 0;

  blocks.forEach((section) => {
    const rules = section.querySelectorAll(".rule");
    let blockMatches = 0;

    rules.forEach((ruleEl) => {
      // Сброс подсветки
      highlightText(ruleEl, "");

      if (!q) {
        ruleEl.hidden = false;
        ruleEl.classList.remove("match");
        return;
      }

      const text = normalize(ruleEl.textContent);
      const isMatch = text.includes(q);

      ruleEl.hidden = !isMatch;
      ruleEl.classList.toggle("match", isMatch);

      if (isMatch) {
        blockMatches++;
        totalMatches++;
        highlightText(ruleEl, query);
      }
    });

    const sectionBlock = section;
    if (q) {
      sectionBlock.hidden = blockMatches === 0;
      if (blockMatches > 0) {
        blocksWithMatches++;
        sectionBlock.classList.add("open");
        sectionBlock.querySelector(".block-header").setAttribute("aria-expanded", "true");
      }
    } else {
      sectionBlock.hidden = false;
      sectionBlock.classList.remove("open");
      sectionBlock.querySelector(".block-header").setAttribute("aria-expanded", "false");
    }
  });

  // Счётчик
  if (!q) {
    countEl.textContent = "";
  } else if (totalMatches === 0) {
    countEl.textContent = "0";
  } else {
    countEl.textContent = `${totalMatches} в ${blocksWithMatches} бл.`;
  }

  // Пустой результат
  if (noResultsEl) {
    noResultsEl.hidden = !(q && totalMatches === 0);
  }
}

/* ============================================================
   ИНИЦИАЛИЗАЦИЯ
   ============================================================ */

render();

let searchTimeout = null;
searchEl.addEventListener("input", (e) => {
  const value = e.target.value;
  clearTimeout(searchTimeout);
  searchTimeout = setTimeout(() => performSearch(value), 120);
});

// Поиск по Enter — без задержки
searchEl.addEventListener("keydown", (e) => {
  if (e.key === "Enter") {
    clearTimeout(searchTimeout);
    performSearch(e.target.value);
  }
});
